(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0027.js"] = [{"id":"glyph-seal-8392","script":"seal","character":"莒","reading":"jǔ","description":"jǔ：(1)古代对芋”的别称。\n(2)中国周代诸侯国名，在今山东省莒县一带。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莒"},{"id":"glyph-seal-8393","script":"seal","character":"莓","reading":"méi","description":"méi：〔草～〕多年生草本植物，叶有长柄，开白花，果实红色，味酸甜。\n〔木～〕落叶灌木，高近二米，果实红色，由多数小核果合成，可食。亦称山莓”、悬钩子”。\n〔寒～〕常绿蔓生小灌木，果实红色，到冬天才熟，可食。\n〔乌蔹～〕蔓生草本植物，开淡黄绿色小花，供药用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莓"},{"id":"glyph-seal-839b","script":"seal","character":"莛","reading":"tíng","description":"tíng：草本植物的茎麦～儿。油菜～儿。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莛"},{"id":"glyph-seal-839e","script":"seal","character":"莞","reading":"wǎn；guān；guǎn","description":"guān：指水葱一类的植物，亦指用其编的席。\nguǎn：〔东～〕地名，在中国广东省。\nwǎn：〔～尔〕形容微笑，如～～一笑”、不觉～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莞"},{"id":"glyph-seal-83a0","script":"seal","character":"莠","reading":"yǒu","description":"yǒu：(1)一年生草本植物，穗有毛，很像谷子，亦称狗尾草”。\n(2)喻品质坏的，不好的人良～不齐。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莠"},{"id":"glyph-seal-83a8","script":"seal","character":"莨","reading":"làng；liáng","description":"làng：〔～菪〕多年生草本植物，根茎块状，叶互生，长椭圆形。种子和根茎、叶均可入药。\nliáng：〔薯～〕多年生草本植物，地下块茎。块茎含有胶质，可用来染棉、麻织品，如～～绸”（亦称香云纱”、拷纱”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莨"},{"id":"glyph-seal-83a9","script":"seal","character":"莩","reading":"piǎo；fú","description":"fú：芦苇秆里面的薄膜葭～。\npiǎo：同殍”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莩"},{"id":"glyph-seal-83aa","script":"seal","character":"莪","reading":"é","description":"é：〔～蒿〕多年生草本植物，生水边，叶像针，开黄绿小花，叶嫩时可食。\n〔～术（zhú）〕多年生草本植物。中医以根状茎入药，称郁金”。全草亦称蓬莪术”、山姜黄”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莪"},{"id":"glyph-seal-83ab","script":"seal","character":"莫","reading":"mò；mù","description":"mò：(1)不要～哭。\n(2)没有，无～大。～非。～名其妙（亦作莫明其妙”）。\n(3)不，不能～如。～逆。～须有。～衷一是（不能得出一致的结论）。爱～能助。\n(4)古同漠”，广大。\n(5)姓。\nmù：古同暮”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莫"},{"id":"glyph-seal-83b1","script":"seal","character":"莱","reading":"lái","description":"草名,又名藜\n郊外休耕的田\n古国名\n长满杂草\n⒈藜。\n⒉［莱菔］萝卜～菔子可供药用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莱"},{"id":"glyph-seal-83b2","script":"seal","character":"莲","reading":"lián","description":"也称芙蓉、芙蕖、菡萏等。多年生草本植物,生浅水中。叶子大而圆,叫荷叶。花有粉红、白色两种。种子叫莲子,包在倒圆锥形的花托内,合称莲蓬。地下茎叫藕\n莲lián即\"荷\"。\n莲liǎn 1.地名用字『有莲勺县。故址在今陕西省渭南县东北。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莲"},{"id":"glyph-seal-83b3","script":"seal","character":"莳","reading":"shì；shí","description":"shì：移栽，种植。shí：用于“莳萝”，一种有香气的草本植物。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-83b7","script":"seal","character":"获","reading":"huò","description":"俘获\n⒈猎得，捉住捕～。俘～。缴～。\n⒉得到，取得～胜归来。不劳而～。～得巨大成绩。\n⒊收割庄稼收～归来。秋～冬藏。也指所取得的成果努力学习，必有收～。\n获hù 1.争取，争得。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-获"},{"id":"glyph-seal-83b8","script":"seal","character":"莸","reading":"yóu","description":"⒈落叶小灌木，花淡蓝或白色带紫纹，供观赏。茎、叶可供药用。\n⒈动植物体内所含的脂肪牛～。菜～。花生～。\n⒉各种碳氢化合物的混合液体。一般不溶于水，易燃烧石～。汽～。\n⒊用油涂抹～剪刀。～窗户。～家具。\n⒋被油弄脏刚穿的新衣，就～了一大块。\n⒌狡猾，浮滑～猾。～嘴。～腔滑调。\n①自然而然的，特指思想感情的产生～然而生。\n②云气盛兴的样子天～然作云。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莸"},{"id":"glyph-seal-83b9","script":"seal","character":"莹","reading":"yíng","description":"似玉的宝石\n光洁透明\n使明洁。使生光泽\n夫良玉未剖,与百石相类;名\n⒈像玉的石头如玉如～。\n⒉光洁，明亮，玉石的光彩晶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莹"},{"id":"glyph-seal-83ba","script":"seal","character":"莺","reading":"yīng","description":"黄莺\n⒈鸟名。种类很多。常见的有树～、柳～、鹪～等。身体多比麻雀小，羽毛绿褐色或灰褐色，嘴尖短，鸣声清脆。主食昆虫，是益鸟，要保护，禁止猎杀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莺"},{"id":"glyph-seal-83bc","script":"seal","character":"莼","reading":"chún","description":"莼菜。亦名水葵”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莼"},{"id":"glyph-seal-83bd","script":"seal","character":"莽","reading":"mǎng","description":"mǎng：(1)草，密生的草～原。草～。\n(2)广大，辽阔～苍。～～（ａ．形容原野辽阔，无边无际；ｂ．形容草木茂盛）。\n(3)古书上指一种短节竹。\n(4)粗鲁，冒失～汉。～撞。鲁～。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-莽"},{"id":"glyph-seal-83c0","script":"seal","character":"菀","reading":"wǎn；yùn","description":"wǎn：草木茂盛的样子。\n〔紫～〕多年生草本植物，茎高二米余，叶有锯齿。根和根茎可入药。\nyùn：古同蕴”，郁结，积滞。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菀"},{"id":"glyph-seal-83c1","script":"seal","character":"菁","reading":"jīng","description":"jīng：(1)韭菜的花秋韭冬～”。\n(2)古代指芜菁”（即蔓菁”）。\n(3)华丽丽服扬～”。\n(4)水草唼喋～藻”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菁"},{"id":"glyph-seal-83c5","script":"seal","character":"菅","reading":"jiān","description":"jiān：多年生草本植物，多生于山坡草地≤坚韧，可做炊帚、刷子等。杆、叶可作造纸原料草～人命。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菅"},{"id":"glyph-seal-83ca","script":"seal","character":"菊","reading":"jú；jv","description":"jú：(1)多年生草本植物，秋天开花，是观赏植物，有的花可以入药，亦可作饮料～花。赏～。春兰秋～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菊"},{"id":"glyph-seal-83cc","script":"seal","character":"菌","reading":"jūn；jùn","description":"jūn：低等植物的一大类，不开花，没有茎和叶子，不含叶绿素，不能自己制造养料，过寄生生活，种类繁多细～。真～。病～。～肥。\njùn：即蕈”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菌"},{"id":"glyph-seal-83cf","script":"seal","character":"菏","reading":"hé","description":"hé：〔～泽〕地名，在中国山东省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菏"},{"id":"glyph-seal-83d4","script":"seal","character":"菔","reading":"fú","description":"fú：〔莱～〕见莱”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菔"},{"id":"glyph-seal-83dc","script":"seal","character":"菜","reading":"cài","description":"cài：(1)供作副食品的植物～市。白～。菠～。野～。蔬～。面有～色。\n(2)主食以外的食品～牛。～畜。～肴。～谱。名～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菜"},{"id":"glyph-seal-83e9","script":"seal","character":"菩","reading":"pú","description":"pú：〔～提〕ａ．佛教指豁然开朗的彻悟境界，又指觉悟的智慧和途径；ｂ．常绿乔木，树上的汁液可制硬性橡胶。原产于印度。\n〔～萨〕ａ．佛教指释迦牟尼修行尚未成佛时的称号，后指修行到一定程度，地位仅次于佛的人；ｂ．泛指佛和某些神；ｃ．喻慈善的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菩"},{"id":"glyph-seal-83f2","script":"seal","character":"菲","reading":"fēi；fěi","description":"fēi：(1)花草茂盛，香气浓郁～～，芳～。\n(2)碳氢化合物的一类，无色有光泽的结晶，可制染料、炸药等。\nfěi：(1)微，薄～才。～仪。～酌。～薄。\n(2)古代指芜菁一类的植物，花紫红色，可作菜用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菲"},{"id":"glyph-seal-83f9","script":"seal","character":"菹","reading":"zū","description":"zū：(1)酸菜，腌菜。\n(2)多水草的沼泽地带～草。\n(3)剁成肉酱，切碎～醢（古代把人剁成肉酱的一种酷刑）。\n(4)肉麋鹿为～。\n(5)枯草～薪。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-菹"},{"id":"glyph-seal-8401","script":"seal","character":"萁","reading":"qí","description":"qí：(1)豆茎豆～。\n(2)古书上说的一种草，像荻而细。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萁"},{"id":"glyph-seal-8403","script":"seal","character":"萃","reading":"cuì","description":"cuì：(1)草丛生，草茂盛的样子。\n(2)聚集～集。～聚。荟～。出类拔～。\n(3)古同悴”，憔悴。\n(4)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萃"},{"id":"glyph-seal-8404","script":"seal","character":"萄","reading":"táo","description":"táo：〔葡～〕见葡”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萄"},{"id":"glyph-seal-840b","script":"seal","character":"萋","reading":"qī","description":"qī：〔～～〕形容草生长茂盛的样子，如芳草～～”。\n〔～斐〕ａ．形容花纹错杂的样子，如萋兮斐兮，成是贝锦；彼潛人者，亦已大甚！”ｂ．喻谗言，如吞决之情深，则～～之辞作。”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萋"},{"id":"glyph-seal-840c","script":"seal","character":"萌","reading":"méng","description":"méng：(1)植物的芽～蘖。\n(2)发芽，开始发生～生。～发。～芽。～动。故态复～。\n(3)古同氓1”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萌"},{"id":"glyph-seal-840d","script":"seal","character":"萍","reading":"píng","description":"píng：一年生草本植物，浮生水面，叶子扁平，表面绿色，背面紫红色，叶下生须根，开白花，称浮萍”，亦称青萍”、紫萍”，多用以喻不定的生活或行踪～泊。～踪。～水相逢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萍"},{"id":"glyph-seal-840e","script":"seal","character":"萎","reading":"wěi","description":"wěi：干枯衰落～谢。～蔫。～顿（亦作委顿”）。～靡。～缩。枯～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萎"},{"id":"glyph-seal-8411","script":"seal","character":"萑","reading":"huán","description":"huán：古代指芦苇一类的植物。\n〔～苻〕中国春秋时郑国沼泽名，据记载，那里密生芦苇，盗贼出没◇因以代指贼之巢穴或盗贼本身。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萑"},{"id":"glyph-seal-841d","script":"seal","character":"萝","reading":"luó","description":"⒈通常指某些能爬蔓的植物茑～。藤～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萝"},{"id":"glyph-seal-8425","script":"seal","character":"营","reading":"yíng","description":"围绕;缠绕\n扎营\n⒈经管，料理经～。国～。私～。～业。～护。\n⒉谋求～利。～救。～私舞弊。无～无欲。\n⒊建造～造。～城市。\n⒋军队驻扎的地方或集体到野外活动的住地军～。夏令～。\n⒌军队编制单位团的下一级，连的上一级。\n①生物从外界摄取需要的养料，以维持生活的作用。\n②养分，养料禽蛋、豆类富于～养。\n营cuō 1.见\"烛营\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-营"},{"id":"glyph-seal-8426","script":"seal","character":"萦","reading":"yíng","description":"牵缠;牵挂\n通荧”。迷惑\n弯曲\n断梗桔槎无拍","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萦"},{"id":"glyph-seal-8427","script":"seal","character":"萧","reading":"xiāo","description":"古国名\n县名\n萧条,冷落;荒凉\n⒈〈古〉称香蒿，也叫\"青蒿\"。\n⒉冷落，冷静～然。～索。\n①冷落寂寞景象～条。\n②停滞，萎缩经济～条。\n①树木被秋风吹动的声音秋风～瑟。\n②冷落凄凉的样子。\n⒎\"萧\"姓，俗写作\"肖\"。\n萧xiāo 1.蒿类植物的一种。即艾蒿。 2.萧条冷落;凄凉。 3.稀疏。 4.指萧斧。 5.见\"萧森\"。 6.见\"萧然\"。 7.通\"肃\"。参见\"萧墙\"﹑\"萧斧\"。 8.古国名。春秋\n时宋的附庸，子姓。在今安徽省萧县西北。公元前597年灭于楚◇仍为宋邑。 9.姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萧"},{"id":"glyph-seal-8431","script":"seal","character":"萱","reading":"xuān","description":"xuān：〔～草〕多年生草本植物，叶条状披针形，花黄色或红黄色，供观赏。亦称金针菜”；简称萱”，如～堂”（借指母亲或母亲居住的地方）。～椿”（指父母）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萱"},{"id":"glyph-seal-8438","script":"seal","character":"萸","reading":"yú","description":"yú：〔茱～〕见茱”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-萸"},{"id":"glyph-seal-843d","script":"seal","character":"落","reading":"luò；là；lào","description":"luò：掉下，下降；停留、归属。là：遗漏，丢下。lào：用于落枕、落色等词。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-8446","script":"seal","character":"葆","reading":"bǎo","description":"bǎo：(1)草茂盛的样子，草木丛生的样子头如蓬～”。\n(2)古书上说的一种菜。\n(3)车盖羽～。\n(4)藏，蔽～光（隐蔽其光不让人知道，喻才智藏而不露）。\n(5)保持～真。永～青春。\n(6)古同宝”，珍贵。\n(7)古同保”，保护。\n(8)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葆"},{"id":"glyph-seal-8451","script":"seal","character":"葑","reading":"fēng","description":"fēng：古书上指蔓菁”、芜菁”～菲（葑”、菲”都是菜名，后用葑菲”表示尚有一德可取的意思，用葑菲之采”为请人有所采用的谦辞）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葑"},{"id":"glyph-seal-845a","script":"seal","character":"葚","reading":"shèn","description":"shèn：桑树结的果实桑～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葚"},{"id":"glyph-seal-845b","script":"seal","character":"葛","reading":"gě；gé","description":"gé：(1)多年生草本植物，茎可编篮做绳，纤维可织布，块根肥大，称葛根”，可制淀粉，亦可入药（通称葛麻”）～布。～巾（葛布做的头巾，古人不分贵贱常服）。～履。\n(2)表面有花纹的纺织品，用丝做经，棉线或麻线等做纬。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葛"},{"id":"glyph-seal-8469","script":"seal","character":"葩","reading":"pā","description":"pā：花，引申为华美～华（花）。奇～异草。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葩"},{"id":"glyph-seal-846c","script":"seal","character":"葬","reading":"zàng","description":"zàng：掩埋死人，泛指处理死者遗体安～。埋～。土～。火～。～。～送。～礼。～仪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葬"},{"id":"glyph-seal-846d","script":"seal","character":"葭","reading":"jiā","description":"jiā：(1)初生的芦苇～芦。～莩（ａ．芦苇中的薄膜；ｂ．喻关系疏远的亲戚，如～～之亲”）。\n(2)古同笳”，一种乐器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葭"},{"id":"glyph-seal-8471","script":"seal","character":"葱","reading":"cōng","description":"cōng：(1)多年生草本植物，叶圆筒状，中空，茎叶有辣味，是常用的蔬菜或调味品，兼作药用，品种很多大～。小～。\n(2)青色～翠。～白。～绿。～茏（形容草木青翠茂盛）。～郁。郁郁～～。\n〔～头〕ａ．多年生草本植物，地下有扁球形鳞，白色或略带紫红色，可食；ｂ．这种植物的鳞茎。亦称洋葱”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葱"},{"id":"glyph-seal-8475","script":"seal","character":"葵","reading":"kuí","description":"kuí：〔向日～〕一年生草本植物，茎很高，开大黄花，花常朝向太阳，子可食，亦可榨油。简称葵”，如～花”，～心”。\n〔锦～〕一年生或多年生草本植物，夏季开淡紫色或白色花，供观赏。\n〔蜀～〕多年生草本植物，花有红、紫、白等色，根可入药。亦称胡葵”、吴葵”、一丈红”。\n〔冬～〕一年生草本植物，果实扁圆形。种子、根、茎、叶均可入药。简称葵”。\n〔蒲～〕常绿乔木，叶大，大部分掌状分裂，裂片长披针形，木材可制器具，叶可做蓑、笠及扇。简称葵”，如～扇”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葵"},{"id":"glyph-seal-847a","script":"seal","character":"葺","reading":"qì","description":"qì：(1)原指用茅草覆盖房子，后泛指修理房屋～墙。～屋（草屋）。修～。\n(2)累积，重叠～袭（重叠）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-葺"},{"id":"glyph-seal-848b","script":"seal","character":"蒋","reading":"jiǎng","description":"古国名\n蒋jiāng 1.植物名。菰。即茭白。 2.见\"蒋蒋\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒋"},{"id":"glyph-seal-848c","script":"seal","character":"蒌","reading":"lóu","description":"蒌蒿\n蒌叶\n蒌liǔ 1.见\"蒌翣\"。\n蒌lǚ 1.见\"萭蒌\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒌"},{"id":"glyph-seal-8499","script":"seal","character":"蒙","reading":"méng；měng","description":"měng：〔～古族〕a.中国少数民族之一。b.蒙古国的主要民族。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒙"},{"id":"glyph-seal-849c","script":"seal","character":"蒜","reading":"suàn","description":"suàn：多年生草本植物，地下鳞茎分瓣，按皮色不同分为紫皮种和白皮种。味辣，有刺激性气味，可食用或供调味，亦可入药（通称大蒜”）～头。～苗。～黄。～毫。～薹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒜"},{"id":"glyph-seal-849f","script":"seal","character":"蒟","reading":"jǔ","description":"用于“蒟酱”，古书中记载的一种植物；也用于植物名“蒟蒻”。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-84b2","script":"seal","character":"蒲","reading":"pú","description":"pú：(1)多年生草本植物，生池沼中，高近两米。根茎长在泥里，可食。叶长而尖，可编席、制扇，夏天开黄色花（亦称香蒲”）～黄（蒲的花粉）。～棒。～草。～绒。～扇。\n(2)指菖蒲”～节。～月（指农历五月）。\n(3)庵，用草盖的圆形屋。\n(4)古同匍”，匍伏。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒲"},{"id":"glyph-seal-84b8","script":"seal","character":"蒸","reading":"zhēng","description":"zhēng：(1)热气上升～汽。～腾。～发。～气（液体或固体因蒸发沸腾或升华而变成的气体）。～馏。云～霞蔚。～～日上。\n(2)用水蒸气的热力把东西加热或使熟～饼。～饺。～笼。\n(3)古代以麻秸、竹木制成的火炬～烛。\n(4)细小的木柴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒸"},{"id":"glyph-seal-84b9","script":"seal","character":"蒹","reading":"jiān","description":"jiān：没有长穗的芦苇～葭倚玉树（喻两人的品貌极不相称）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒹"},{"id":"glyph-seal-84bf","script":"seal","character":"蒿","reading":"hāo","description":"hāo：(1)二年生草本植物，叶如丝状，有特殊的气味，开黄绿色小花，可入药（亦称青蒿”、香蒿”）～莱（杂草，喻草野百姓）。\n(2)气蒸出的样子。\n(3)消耗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蒿"},{"id":"glyph-seal-84c1","script":"seal","character":"蓁","reading":"zhēn","description":"zhēn：同榛”②。\n〔～～〕a.草木茂盛的样子；b.荆棘丛生的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓁"},{"id":"glyph-seal-84c4","script":"seal","character":"蓄","reading":"xù","description":"xù：(1)积聚，储藏，保存～藏。～洪。～发（fà）。～养。积～。储～。兼收并～。\n(2)存于心中～志。～怨。～谋。～意‖～。\n(3)等待孰谓时之可～？”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓄"},{"id":"glyph-seal-84c9","script":"seal","character":"蓉","reading":"róng","description":"róng：(1)用某些植物的果肉或种子制成的粉状物椰～。豆～。\n(2)中国四川省成都市的别称～城。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓉"},{"id":"glyph-seal-84cd","script":"seal","character":"蓍","reading":"shī","description":"蓍草，多年生草本植物，古人曾用其茎进行占筮。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-84d0","script":"seal","character":"蓐","reading":"rù","description":"rù：陈草复生，引申为草垫子，草席～妇（产妇）。～母（接生婆）。坐～（临产）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓐"},{"id":"glyph-seal-84dd","script":"seal","character":"蓝","reading":"lán","description":"佛寺。梵语伽蓝的简称\n颜色的一种。像晴天天空的颜色\n⒈蓝色，像晴空那样的颜色～天。天～色。\n⒉蓼蓝，一年生草本。叶子提制的靛青，可做染料，染出的颜色就是青青出于～，而胜于～。\n⒊［蓝本］著作所依据的原本。\n⒋［蓝图］一种复制图。〈喻〉建设的计划。\n蓝lan 1.苤蓝。甘蓝的一种。是普通蔬菜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓝"},{"id":"glyph-seal-84df","script":"seal","character":"蓟","reading":"jì","description":"古州名\n古县名\n蓟县。秦置。治所在今北京城西南\n县名。在天津市北部,邻接北京市和河北省。秦置无终县,隋改渔阳县,明入蓟州,1913年改为蓟县\n蓟jì多年生草本，春天发芽，茎叶有刺和白色软毛，花紫红色。分大蓟和小蓟。全草供药用。嫩茎叶可食或作饲料。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓟"},{"id":"glyph-seal-84e0","script":"seal","character":"蓠","reading":"lí","description":"红藻的一种。也叫龙须菜”\n古书上说的一种香菜\n蓠 lí 〈名〉即\"江蓠 \"。藻类植物的一种。暗红色。可用来制琼脂。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓠"},{"id":"glyph-seal-84e5","script":"seal","character":"蓥","reading":"yíng","description":"琢磨使发光。亦作莹”\n蓥yīng 1.古代一种长颈瓶。短足，似眀。 2.磨拭使光亮。 3.明亮。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓥"},{"id":"glyph-seal-84e6","script":"seal","character":"蓦","reading":"mò","description":"突然,忽然\n蓦mò忽然，突然～然。～地。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓦"},{"id":"glyph-seal-84ec","script":"seal","character":"蓬","reading":"péng","description":"péng：(1)多年生草本植物，花白色，中心黄色，叶似柳叶，子实有毛（亦称飞蓬”）～门。～心（蓬”的心狭窄而弯曲，喻茅塞不通的头脑。谦辞，用以表示自己见识浅陋，蠢笨）。～户瓮牗。～生麻中（喻在良好的生长环境里，自然会受到好的影响）。～荜生辉（使得自家有了光彩。谦辞，用来称谢别人字画等物品的赠予或客人的来访）。\n(2)散乱～乱。～松。～头垢面。\n(3)茂盛，旺盛～勃。\n(4)量词，用于类似成丛飞蓬的东西一～凤尾竹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓬"},{"id":"glyph-seal-84fc","script":"seal","character":"蓼","reading":"liǎo；lù","description":"liǎo：一年生草本植物，叶披针形，花小，白色或浅红色，果实卵形、扁平，生长在水边或水中。茎叶味辛辣，可用以调味。全草入药。亦称水蓼”。\nlù：形容植物高大。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蓼"},{"id":"glyph-seal-8511","script":"seal","character":"蔑","reading":"miè","description":"细小;轻微\n轻视;轻侮。亦作懱”\n⒈微小～视。\n⒉无～不济矣。\n⒊污血。〈引〉以血涂人，即诋毁别人污～。诬～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔑"},{"id":"glyph-seal-8513","script":"seal","character":"蔓","reading":"màn；wàn","description":"wàn：细长能缠绕的茎瓜～儿。\n〔大～儿（wànr）〕方言，指有较高表演技艺，有广泛影响的演艺明星。亦作大腕儿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔓"},{"id":"glyph-seal-8517","script":"seal","character":"蔗","reading":"zhè","description":"zhè：〔甘～〕多年生草本植物，茎直立，有节，含甜汁很多，可生吃，亦可制糖。副产品糖蜜可酿酒、制酒精。简称蔗”，如～农”。～糖”。～渣”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔗"},{"id":"glyph-seal-851a","script":"seal","character":"蔚","reading":"wèi","description":"wèi：(1)茂盛，荟聚，盛大～然成风。～为大观。～蓝（晴朗天空的颜色）。\n(2)文采华丽云蒸霞～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔚"},{"id":"glyph-seal-851f","script":"seal","character":"蔟","reading":"cù","description":"cù：(1)蚕在上面做茧的东西，通常用稻草做成蚕～。\n(2)古同簇”，丛聚。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔟"},{"id":"glyph-seal-8521","script":"seal","character":"蔡","reading":"cài","description":"cài：(1)野草。\n(2)中国周代诸侯国名，在今河南省上蔡县、新蔡县一带。\n(3)占卜用的大龟蓍～。\n(4)杀，减三百里夷，二百里～”。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔡"},{"id":"glyph-seal-852b","script":"seal","character":"蔫","reading":"niān","description":"niān：(1)植物失去水分而萎缩花～了。\n(2)精神不振，不活泼他这几天～了。～头耷脑。\n(3)不声不响，悄悄～不声。～溜儿。～儿拱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔫"},{"id":"glyph-seal-852c","script":"seal","character":"蔬","reading":"shū","description":"shū：可做菜吃的植物（多属草本）～菜。菜～。布衣～食。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔬"},{"id":"glyph-seal-8537","script":"seal","character":"蔷","reading":"qiáng","description":"这种植物的花。有单瓣、复瓣之别,色有红、粉红、白、黄等多种,很美丽,初夏开放\n蔷sè 1.水蓼。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔷"},{"id":"glyph-seal-853a","script":"seal","character":"蔺","reading":"lìn","description":"一种多年生草本植物,也称马蔺\n假借为棱”\n通躏”。车轮碾压\n蔺相如","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔺"},{"id":"glyph-seal-853c","script":"seal","character":"蔼","reading":"ǎi","description":"树木生长繁茂\n盛多的样子\n和气,态度好\n云气。通霭”\n蔼 ǎi和气，和善对人和～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔼"},{"id":"glyph-seal-853d","script":"seal","character":"蔽","reading":"bì","description":"bì：(1)遮，挡～野。遮～。掩～。\n(2)隐藏～匿。隐～。\n(3)欺骗，隐瞒蒙～。～美扬恶。\n(4)概括一言以～之。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蔽"},{"id":"glyph-seal-8543","script":"seal","character":"蕃","reading":"fān；fán","description":"fán：(1)茂盛～茂。～昌。～芜。\n(2)繁多～衍（同繁衍”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蕃"},{"id":"glyph-seal-8548","script":"seal","character":"蕈","reading":"xùn","description":"xùn：生长在树林里或草地上的某些高等菌类植物，伞状，种类很多，有的可食，有的有毒毒蝇～。香～。松～。\n〔～树〕常绿乔木，高十余米。叶侧卵形，结蒴果。为优质木材。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蕈"},{"id":"glyph-seal-8549","script":"seal","character":"蕉","reading":"jiāo","description":"jiāo：(1)指某些有像芭蕉那样的大叶子的植物香～。美人～。\n(2)生麻，未沤治的麻。\n(3)古同焦”，枯焦。\n〔芭～〕见芭”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蕉"},{"id":"glyph-seal-8564","script":"seal","character":"蕤","reading":"ruí","description":"ruí：(1)草木的花下垂的样子。\n(2)指下垂的缨类装饰物。\n〔葳～〕草木茂盛的样子。\n〔～宾〕a.中国古代音乐十二律中的第七律；b.农历五月的别称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蕤"},{"id":"glyph-seal-8568","script":"seal","character":"蕨","reading":"jué","description":"jué：多年生草本植物，根茎长。嫩叶可食，根茎可制淀粉，其纤维可制绳缆，耐水。全株入药。\n〔～类植物〕植物的一大类，草本，很少木本，有根、茎和叶，用孢子繁殖，生长在森林和山野的阴湿地带，如蕨”、石松”等。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蕨"},{"id":"glyph-seal-8572","script":"seal","character":"蕲","reading":"qí","description":"一种香草\n古州名\n通圻”。疆界\n通祈”。祈求\n蕲至于古之立言者。\n⒈通\"祈\"。祈求。\n蕲jī 1.古县名。本战国时楚邑，秦置蕲县，汉属沛郡。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蕲"},{"id":"glyph-seal-8584","script":"seal","character":"薄","reading":"báo；bó；bò","description":"báo：厚度小，如薄纸。bó：微少，不厚道；轻视，如薄礼、刻薄、厚古薄今。bò：用于薄荷。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-8585","script":"seal","character":"薅","reading":"hāo","description":"hāo：(1)拔除～草。～锄。\n(2)揪。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薅"},{"id":"glyph-seal-8587","script":"seal","character":"薇","reading":"wēi","description":"wēi：一年生或二年生草本植物，结荚果，中有种子五六粒，可食。嫩茎和叶可做蔬菜。通称巢菜”、大巢菜”、野豌豆”。\n〔紫～〕a.落叶小乔木。开紫红色或白色花，结球形蒴果。供观赏；b.这种植物的花。均通称满堂红”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薇"},{"id":"glyph-seal-859b","script":"seal","character":"薛","reading":"xuē","description":"xuē：(1)中国周代诸侯国名，在今山东省滕县南。\n(2)古书上指一种蒿类植物。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薛"},{"id":"glyph-seal-859c","script":"seal","character":"薜","reading":"bì","description":"bì：(1)古书上指当归。\n(2)古书上指野麻。\n〔～荔〕常绿灌木，茎蔓生，果实球形，可做淀粉，捣汁可做饮料。简称薜”，如～萝”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薜"},{"id":"glyph-seal-85a8","script":"seal","character":"薨","reading":"hōng","description":"hōng：古代称诸侯或有爵位的大官死去。\n〔～～〕成群的昆虫一起飞的声音，如虫飞～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薨"},{"id":"glyph-seal-85aa","script":"seal","character":"薪","reading":"xīn","description":"xīn：柴火～苏（打柴割草）。～尽火传（chuán）（柴火烧完，又引燃了后一根柴，火永远不灭。原指人形骸有尽而精神未死，后亦用以喻思想学问、技艺代代相传）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薪"},{"id":"glyph-seal-85ae","script":"seal","character":"薮","reading":"sǒu","description":"sǒu：(1)生长着很多草的湖泽～泽。\n(2)人或物聚集的地方渊～。\n(3)指民间、草野辞朝（cháo）归～。\n(4)古同搜”，搜求。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薮"},{"id":"glyph-seal-85af","script":"seal","character":"薯","reading":"shǔ","description":"shǔ：〔～莨〕a.多年生草本植物，地上有缠绕茎，地下块茎，可用来染棉、麻织品；b.这种植物的果实。\n〔～蓣〕多年生草本植物，茎蔓生，块根为圆柱形，可食。通称山药”。\n〔甘～〕a.一年生或多年生草本植物，蔓匍匐地面。块根可食，亦可制糖和酒精；b.这种植物的块根。均通称红薯”、白薯”；亦称番薯”、山芋”、地瓜”、红苕”。\n〔马铃～〕a.多年生草本植物，地下块茎可食；ｂ．这种植物的块茎。均亦称土豆儿”、山药蛋”、洋芋”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薯"},{"id":"glyph-seal-85b0","script":"seal","character":"薰","reading":"xūn","description":"xūn：(1)同熏”。\n(2)古书上说的一种香草，又泛指花草的香气～莸不同器（香草和臭草不能放在一个器物里，喻好和坏不能共存。亦称薰莸异器”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-薰"},{"id":"glyph-seal-85c9","script":"seal","character":"藉","reading":"jiè；jí","description":"jiè：(1)垫在下面的东西。\n(2)衬垫枕～。\n(3)同借”③④。\n(4)抚慰慰～。\n(5)含蓄蕴～。\n(6)假设，假使公等遇雨，皆已失期，失期当斩。～第令毋斩，而戍死者固十六七”。\njí：(1)践踏，凌辱人皆～吾弟”。狼～。\n(2)进贡其～于成周”。\n(3)姓。\n〔～～〕同籍籍”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-藉"},{"id":"glyph-seal-85cf","script":"seal","character":"藏","reading":"cáng；zàng","description":"cáng：隐藏、收藏。zàng：储藏东西的地方；佛教等经典的总汇；用于西藏、藏族等名称。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-85dc","script":"seal","character":"藜","reading":"lí","description":"lí：一年生草本植物，茎直立，嫩叶可吃。茎可以做拐杖（亦称灰条菜”）～仗。～藿（指粗劣的饭菜）。\n〔～芦〕多年生草本植物，叶细长，花紫黑色，有毒，可入药。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-藜"},{"id":"glyph-seal-85e9","script":"seal","character":"藩","reading":"fān","description":"fān：(1)篱笆～篱。\n(2)屏障，保卫～翰（喻保卫国家的重臣）。\n(3)封建时代称属国属地或分封的土地，借指边防重镇～属。～国。～镇。～邦。削～。称～（自称属国）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-藩"},{"id":"glyph-seal-85fb","script":"seal","character":"藻","reading":"zǎo","description":"zǎo：(1)隐花植物的一大类，无根、茎、叶等部分的区别，有叶绿素可以自己制造养料，种类很多，海水和淡水里都有，极少数可生活在陆地的阴湿地方水～。～。小球～。～类植物。\n(2)泛指生长在水中的植物，亦包括某些水生的高等植物狸～。金鱼～。\n(3)指华丽的文彩、文辞～思（多采的文思）。～丽。～绘（文采）。～井（中国传统建筑物天花板上一方一方的彩画）。～镜（指品评鉴别。亦称藻鉴”）。辞～。～饰。\n(4)古代帝王冕上系玉的五彩丝绳玉～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-藻"},{"id":"glyph-seal-85ff","script":"seal","character":"藿","reading":"huò","description":"huò：豆类植物的叶子～食（指粗劣的食物）。\n〔～香〕多年生草本植物，叶子心脏形，花蓝紫色，瘦果倒卵性。茎叶香气很浓，可入药。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-藿"},{"id":"glyph-seal-8616","script":"seal","character":"蘖","reading":"niè","description":"niè：树木砍去后从残存茎根上长出的新芽，泛指植物近根处长出的分枝～枝。分～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蘖"},{"id":"glyph-seal-8627","script":"seal","character":"蘧","reading":"qú","description":"qú：(1)惊喜的样子～然。～～。\n(2)古同蕖”，芙蕖，荷花。\n(3)姓。\n〔～麦〕即瞿麦”。\n〔～庐〕古代称旅舍。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蘧"},{"id":"glyph-seal-8629","script":"seal","character":"蘩","reading":"fán","description":"fán：白蒿。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蘩"},{"id":"glyph-seal-8638","script":"seal","character":"蘸","reading":"zhàn","description":"zhàn：在液体、粉末或糊状的东西里沾一下就拿出来～水钢笔。～糖吃。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蘸"},{"id":"glyph-seal-864e","script":"seal","character":"虎","reading":"hǔ","description":"hǔ：(1)哺乳动物，毛黄褐色，有黑色条纹，性凶猛，力大。骨和血及内脏均可入药（通称老虎”）～口（a.喻危险境地；b.手上拇指和食指相交的地方）。～穴（喻危险境地）。～符（古代调兵的凭证，用铜铸成虎形，分两半）。～狼（喻凶残的人）。～头蛇尾。～踞龙盘。龙腾～跃。\n(2)勇猛、威武～将。～势。～劲。～威。～～。～气。\n(3)古同唬”，威吓。\n(4)古同琥”，琥珀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虎"},{"id":"glyph-seal-864f","script":"seal","character":"虏","reading":"lǔ","description":"亦指虏掠、抄掠\n⒈俘获～获。俘～敌军万余人。\n⒉打仗时捉到的敌人优待俘～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虏"},{"id":"glyph-seal-8650","script":"seal","character":"虐","reading":"nüè","description":"nüè：残暴暴～。～待。～政（暴政）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虐"},{"id":"glyph-seal-8651","script":"seal","character":"虑","reading":"lǜ；lv","description":"用绳结缀\n今子有\n⒈打算，思考，谋划考～。深思熟～。深谋远～。\n⒉担忧忧～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虑"},{"id":"glyph-seal-8654","script":"seal","character":"虔","reading":"qián","description":"qián：恭敬～诚。～敬。～心。～信。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虔"},{"id":"glyph-seal-865a","script":"seal","character":"虚","reading":"xū","description":"xū：(1)空～无。～实。～度。～名。～左（尊敬地空出左边的座位，古代以左为尊）。空～。乘～而入。\n(2)不真实的～伪。～假（jiǎ）。～妄。～惊。～夸。～构。～传。～张声势。\n(3)内心怯懦做贼心～。\n(4)不自满～心。谦～。～怀若谷（喻对人十分谦虚）。\n(5)抽象的～词。\n(6)衰弱～弱。～胖。～汗。～脱。气～。血～。\n(7)星名，二十八宿之一。\n(8)古同墟”，大丘。\n(9)古同圩”，集市。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虚"},{"id":"glyph-seal-865e","script":"seal","character":"虞","reading":"yú","description":"yú：(1)预料不～。\n(2)忧虑无冻馁之～。\n(3)欺骗尔～我诈。\n(4)中国周代诸侯国名，在今山西省平陆县东北。\n(5)古同娱”，安乐。\n(6)古代掌管山泽的官～人（中国春秋战国时称）。\n(7)传说中的中国朝代名，舜所建。\n(8)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虞"},{"id":"glyph-seal-8662","script":"seal","character":"虢","reading":"guó","description":"guó：(1)中国周代诸侯国名东～（在今河南省郑州市西北）。西～（在今陕西省宝鸡县东，后迁到今河南省陕县东南）。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虢"},{"id":"glyph-seal-866b","script":"seal","character":"虫","reading":"chóng","description":"虫 chóng昆虫和类似昆虫的小动物。\n【虫草】子囊菌纲菌丝冬天侵入一些鳞翅目昆虫幼虫体内，使虫体变成充满菌丝的僵壳。夏季虫体长出具柄的棒形子座，故名。生于高山草原。能补肺益肾。又叫冬虫夏草。\n【虫媒花】〈生〉依靠昆虫传送花粉的花。其特征是花大，色鲜；有蜜腺和香味；花粉较大，外壁有突起或粘质；有集中成簇的花序。\n【虫瘿】〈生〉植物的幼枝嫩叶组织受昆虫刺伤及分泌物刺激，细胞加速分裂而长成的囊肿状构造。我国盛产的五倍子就是由一种蚜虫在盐肤木上形成的虫瘿。\n【虫豸】虫子。\n虫huǐ 1.毒蛇名◇写作\"虺\"。\n虫tóng 1.见\"虫虫\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虫"},{"id":"glyph-seal-866c","script":"seal","character":"虬","reading":"qiú","description":"qiú：(1)古代传说中有角的小龙～龙。\n(2)拳曲～曲（盘绕弯曲）。～须。～髯（拳曲的胡须，特指两腮上的胡须）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虬"},{"id":"glyph-seal-866e","script":"seal","character":"虮","reading":"jǐ","description":"虮子,即虱卵,虱的卵\n酒面上的浮沫","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虮"},{"id":"glyph-seal-8671","script":"seal","character":"虱","reading":"shī","description":"虱（蝨）shī寄生在人、畜身上，吸食血液的一种昆虫。有头～。体～子、阴～子等。能传播斑疹伤寒、回归热等疾病讲卫生，爱清洁，消灭～子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虱"},{"id":"glyph-seal-8679","script":"seal","character":"虹","reading":"hóng","description":"hóng：(1)雨后天空中出现的彩色圆弧，有红、橙、黄、绿、蓝、靛、紫七种颜色。是大气中的小水珠经日光照射发生折射和反射作用而形成的，出现在和太阳相对着的方向。\n(2)指桥（因形似虹）～桥（中国古代的一种木拱桥。外形如长虹贯空。亦称飞桥”）。断～。长～卧波。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虹"},{"id":"glyph-seal-867a","script":"seal","character":"虺","reading":"huī；huǐ","description":"huǐ：古书上说的一种毒蛇～蜮（虺、蜴、蜮都是害人的毒物，喻奸恶小人）。为～弗摧，为蛇若何（小蛇不打死，成了大蛇怎么办？原喻要趁敌人弱小时就把它消灭，后泛指坏人要及早除掉）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虺"},{"id":"glyph-seal-867d","script":"seal","character":"虽","reading":"suī","description":"即使…也;纵使\n仅,只\n原本,本\n你那里休夸口,你虽是一人为害,\n⒈连词。即使，纵然～然。麻雀～小，肝胆俱全。为人民的利益而死，～死犹生。会议～短，但可解决问题。\n⒉只，仅有～有。\n虽wèi 1.兽名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虽"},{"id":"glyph-seal-867e","script":"seal","character":"虾","reading":"xiā","description":"动物名\n像虾一样弯曲\n满语对侍卫的称呼\n⒈节肢动物。体分头、胸、腹，外被甲壳，腹部有多个环节，生活在水里。有龙～、对～、米～等多种，都可食用。\n虾há 1.青蛙和蟾蜍的统称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-虾"},{"id":"glyph-seal-8680","script":"seal","character":"蚀","reading":"shí","description":"损失;亏耗\n日月食\n⒈虫蛀东西蛀～。\n⒉损伤，亏损侵～。腐～。～本。\n⒊同\"食\n⒊\"日～。月～。\n蚀lì 1.谷名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚀"},{"id":"glyph-seal-868a","script":"seal","character":"蚊","reading":"wén","description":"wén：昆虫，种类很多。雄的吸植物的汁液，雌的吸人畜的血液，有的传染疾病。幼虫称孑孓”～子。～香。～帐。聚～成雷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚊"},{"id":"glyph-seal-868b","script":"seal","character":"蚋","reading":"ruì","description":"ruì：昆虫，体长二、三毫米，头小，色黑，胸背隆起，吸人畜的血液，幼虫栖于水中。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚋"},{"id":"glyph-seal-868c","script":"seal","character":"蚌","reading":"bàng；bèng","description":"bàng：生活在淡水里的一种软体动物，介壳长圆形，表面黑褐色，壳内有珍珠层，有的可以产出珍珠～胎（指珍珠）。\nbèng：〔～埠（bù）〕地名，在中国安徽省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚌"},{"id":"glyph-seal-868d","script":"seal","character":"蚍","reading":"pí","description":"pí：〔～蜉〕大蚂蚁，如～～撼大树”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚍"},{"id":"glyph-seal-8693","script":"seal","character":"蚓","reading":"yǐn","description":"yǐn：〔蚯～〕见蚯”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚓"},{"id":"glyph-seal-8695","script":"seal","character":"蚕","reading":"cán","description":"蚕事。养蚕的工作\n养蚕\n蚕 cán同\"衠\"。\"衠\"的简化字。\n①昆虫名。幼虫能吐丝﹑结茧。有家蚕﹑柞蚕等。茧丝为重要的纤维资源。\n②养蚕。\n③蚕事;养蚕的工作。\n④侵蚀。\n⑤引申为侵害者。\n⑥传说蜀地开辟者蚕丛的简称。参见\"衠鴌\"。\n⑦见\"衠兒\"。\n蚕tiǎn 1.蝧蚕。蚯蚓的别名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚕"},{"id":"glyph-seal-86a3","script":"seal","character":"蚣","reading":"gōng；zhōng","description":"gōng：〔蜈～〕见蜈”。\nzhōng：〔～蝑〕即螽斯”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚣"},{"id":"glyph-seal-86a4","script":"seal","character":"蚤","reading":"zǎo","description":"zǎo：(1)昆虫，赤褐色，善跳跃，寄生在人和畜的身体上，吸血液，能传染鼠疫等疾病。通称跳蚤”、虼蚤”。\n(2)古同早”。\n(3)古同爪”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚤"},{"id":"glyph-seal-86a8","script":"seal","character":"蚨","reading":"fú","description":"fú：〔青～〕a.古书上说的一种虫；b.古代用作钱的别称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚨"},{"id":"glyph-seal-86a9","script":"seal","character":"蚩","reading":"chī","description":"chī：(1)无知，痴愚～拙（粗俗笨拙）。～～。\n(2)古同嗤”，讥笑。\n(3)古同媸”，丑陋。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚩"},{"id":"glyph-seal-86ac","script":"seal","character":"蚬","reading":"xiǎn","description":"小蛤的一类\n蚬xiǎn软体动物。介壳略呈心脏形，外面青黑或黄褐色，有环纹，里面青紫或白色。生活在淡水软泥中。肉可吃，壳可供药用 。\n蚬xiàn 1.蝶类的幼虫。赤头，长寸许，吐丝作茧，悬于空中，俗名缢女。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蚬"},{"id":"glyph-seal-86c4","script":"seal","character":"蛄","reading":"gū","description":"gū：〔蝼～〕见蝼”。\n〔蟪～〕见蟪”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛄"},{"id":"glyph-seal-86c7","script":"seal","character":"蛇","reading":"shé；yí","description":"shé：爬行动物，身体细长，体上有鳞，没有四肢。种类很多，有的有毒，有的无毒。以蛙、鼠为食，大蛇亦吞食大的兽类～蜕。～行。～蝎。～足（喻多余无用的事物）。画～添足。\nyí：〔委（wēi）～〕见委2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛇"},{"id":"glyph-seal-86c9","script":"seal","character":"蛉","reading":"líng","description":"líng：〔白～子〕一种比蚊子小的小飞虫，喜吸人畜血液，能传染黑热病。\n〔螟～〕见螟”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛉"},{"id":"glyph-seal-86ca","script":"seal","character":"蛊","reading":"gǔ","description":"同 本 义\n毒虫。传说荣虫于皿中,使互相蚕食,最后所剩的一虫为蛊\n神智惑乱的疾病\n传说中一种人工培育的毒虫\n江南数郡有畜蛊者,主人行之以杀人,行食饮中,人不\n⒈〈古〉传说把许多毒虫放在器皿里，使互相吞食，最后剩下不死的毒虫叫蛊，传说用于毒害人毒～。\n⒊指陈旧的谷中所生的虫谷虫曰～。～若蛾矣。\n⒋迷惑，欺骗，扰乱～惑人心。～世危言。\n蛊yě 1.冶媚;妖艳。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛊"},{"id":"glyph-seal-86d4","script":"seal","character":"蛔","reading":"huí","description":"huí：〔～虫〕寄生在人或其他动物肠子里的一种蠕形动物，像蚯蚓而没有环节。能损害人畜的健康。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛔"},{"id":"glyph-seal-86d8","script":"seal","character":"蛘","reading":"yáng","description":"yáng：生在米里的一种小黑甲虫。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛘"},{"id":"glyph-seal-86d9","script":"seal","character":"蛙","reading":"wā","description":"wā：两栖动物的一科，无尾，后肢长，前肢短，趾有蹼，善于跳跃和泅水。种类很多青～（俗称田鸡”）。牛～。～泳。～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛙"},{"id":"glyph-seal-86db","script":"seal","character":"蛛","reading":"zhū","description":"zhū：指蜘蛛”～网。～丝马迹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛛"},{"id":"glyph-seal-86df","script":"seal","character":"蛟","reading":"jiāo","description":"jiāo：(1)古代传说中一种能发洪水的龙～龙得水。\n(2)指鼍、鳄之类的动物。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛟"},{"id":"glyph-seal-86e4","script":"seal","character":"蛤","reading":"há；gé","description":"gé：〔～蜊〕软体动物，壳形卵圆，色淡褐，稍有轮纹，内白色，栖浅海沙中，肉可食。\n〔文～〕软体动物，略呈三角形，栖近海沙泥中，有黑白两种，幼时称棋子蛤”。\n〔～蚧〕爬行动物，土黄色，像壁虎，头大，尾部灰色，有红色斑点。中医用作强壮剂。\nhá：〔～蟆〕青蛙和蟾蜍的统称（蟆”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛤"},{"id":"glyph-seal-86e9","script":"seal","character":"蛩","reading":"qióng","description":"qióng：(1)蝗虫飞～满野”。\n(2)蟋蟀～唱。～响。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛩"},{"id":"glyph-seal-86ed","script":"seal","character":"蛭","reading":"zhì","description":"zhì：〔水～〕环节动物，身体长形，稍扁，墨绿色，尾端有吸盘，雌雄同体生活在池沼或水田中，能吸人畜的血。唾液中含有水蛭素，医学上能发挥抗凝血作用。虫体经干燥炮制后入中药。俗称蚂蟥”马鳖”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛭"},{"id":"glyph-seal-86ee","script":"seal","character":"蛮","reading":"mán","description":"⒈粗野，强横野～。～横。～缠。～不讲理。\n⒉愣，强悍～劲。～干。\n⒊〈方〉很，挺～好。～大。\n⒋〈古〉我国称南方的民族南～。〈引〉南，南方思彼～方。泛指少数民族北～。\n⒌边远地区～荒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛮"},{"id":"glyph-seal-86f0","script":"seal","character":"蛰","reading":"zhé","description":"虫类伏藏洞穴不出\n喻潜藏而未披露","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛰"},{"id":"glyph-seal-86f1","script":"seal","character":"蛱","reading":"jiá","description":"用于“蛱蝶”，一类蝴蝶的名称。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-86f2","script":"seal","character":"蛲","reading":"náo","description":"蛲虫\n蛲rào 1.虫动貌。参见\"蛲动\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛲"},{"id":"glyph-seal-86f8","script":"seal","character":"蛸","reading":"shāo；xiāo","description":"xiāo：〔螵～〕见螵”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛸"},{"id":"glyph-seal-86f9","script":"seal","character":"蛹","reading":"yǒng","description":"yǒng：昆虫从幼虫过渡到成虫时的一种形态蚕～。～化。～卧（蚕蛹蜷伏茧中，喻隐居）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛹"},{"id":"glyph-seal-86fe","script":"seal","character":"蛾","reading":"é；yǐ","description":"é：昆虫，与蝴蝶相似，体肥大，触角细长如丝，翅面灰白，静止时，翅左右平放，常在夜间活动，有趋光性～子。～眉。～扬（眉扬，形容美人笑貌）。～绿。飞～扑火。\nyǐ：古同蚁”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蛾"},{"id":"glyph-seal-8700","script":"seal","character":"蜀","reading":"shǔ","description":"shǔ：(1)中国四川省的别称～本（宋代在四川刻印的书籍）。～客（旅游蜀地的人）。～椒。～绣（四川出产的刺绣）。～锦。得陇望～。\n(2)中国朝代名～汉。\n(3)中国周代诸侯国名，在今四川省成都市一带。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜀"},{"id":"glyph-seal-8702","script":"seal","character":"蜂","reading":"fēng","description":"fēng：(1)昆虫，会飞，多有毒刺，能蜇人。有蜜蜂”、熊蜂”、胡蜂”、细腰蜂”等多种，多成群住在一起。\n(2)特指蜜蜂”～巢。～房。～蜡。～蜜。～乳。～王（生殖器官发育完全的雌蜂，专司产卵，通常每个蜂群只有一只。亦称母蜂”）。～腰（a.蜂腰中间细，喻居中者最差；b.诗律八病”之一；c.书法笔病之一）。\n(3)众多～起。～拥。～聚。～集。\n〔～鸟〕鸟类中最小的一种，大小如大拇指，嘴细长。吃花蜜和花上的小昆虫。产于南美洲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜂"},{"id":"glyph-seal-8703","script":"seal","character":"蜃","reading":"shèn","description":"shèn：蛤蜊～景（亦称海市蜃楼”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜃"},{"id":"glyph-seal-8709","script":"seal","character":"蜉","reading":"fú","description":"用于“蜉蝣”，一种昆虫，成虫寿命通常很短。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-8713","script":"seal","character":"蜓","reading":"tíng","description":"tíng：〔蜻（qīng）～〕见蜻1”。\n〔??～〕见蝘”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜓"},{"id":"glyph-seal-8715","script":"seal","character":"蜕","reading":"tuì","description":"tuì：(1)蝉或蛇等脱下来的皮蛇～。蝉～。\n(2)蛇、蝉等动物脱皮～皮。\n(3)鸟换毛。\n(4)解脱，变化～化。～变。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜕"},{"id":"glyph-seal-8717","script":"seal","character":"蜗","reading":"wō","description":"动物名,蜗牛\n蜗luó 1.见\"蜗醢\"﹑\"蜗旋\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜗"},{"id":"glyph-seal-8718","script":"seal","character":"蜘","reading":"zhī","description":"zhī：〔～蛛〕节肢动物，身体圆形或长圆形，分头胸和腹两部，有触须和脚四对。肛门分泌的黏液凝成细丝，用来结网捕食昆虫。通称蛛蛛”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜘"},{"id":"glyph-seal-871a","script":"seal","character":"蜚","reading":"fēi","description":"fēi：古同飞”，指无根据的、无缘无故的。现流言飞语”常写作流言蜚语”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜚"},{"id":"glyph-seal-871c","script":"seal","character":"蜜","reading":"mì","description":"mì：(1)蜜蜂采取花的甜汁酿成的东西蜂～。～饯。～供（把油炸的短面条拌上蜜或糖制成的糕点）。～源（指能大量供蜜蜂采蜜的植物）。～丸。\n(2)甜美甜言～语。口～腹剑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜜"},{"id":"glyph-seal-8721","script":"seal","character":"蜡","reading":"là","description":"动物、矿物或植物所产生的油质,具有可塑性,能燃能熔,不溶于水,是一羟基醇或固醇的脂肪酸酯\n蜡烛的简称\n用蜡涂抹\n⒈动、植、矿物所产生的一种油质，易熔化，具有可塑性，不溶于水蜂～。白～。石～。\n⒉蜡烛的简称拿支～来。\n⒊色淡黄像蜡的～黄。～梅。\n⒈〈古〉夏历年终的一种祭祀～祭。\n蜡qù 1.蝇蛆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜡"},{"id":"glyph-seal-8722","script":"seal","character":"蜢","reading":"měng","description":"měng：〔蚱～〕见蚱”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜢"},{"id":"glyph-seal-8725","script":"seal","character":"蜥","reading":"xī","description":"xī：〔～蜴〕爬行动物，有四肢，尾巴很长，容易断，脚上有钩爪。生活在草丛里，捕食昆虫和其他小动物。通称四脚蛇”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜥"},{"id":"glyph-seal-8729","script":"seal","character":"蜩","reading":"tiáo","description":"tiáo：古书上指蝉～甲（蝉蜕）。世事～螗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜩"},{"id":"glyph-seal-872e","script":"seal","character":"蜮","reading":"yù","description":"yù：传说中一种在水里暗中害人的怪物鬼～（喻阴险的人）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜮"},{"id":"glyph-seal-8731","script":"seal","character":"蜱","reading":"pí","description":"pí：蜘蛛一类的动物，体形扁平，种类很多，有的吸植物汁液，有的吸人畜的血，传染疾病。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜱"},{"id":"glyph-seal-873b","script":"seal","character":"蜻","reading":"qīng","description":"qīng：〔～蜓〕昆虫，捕食小飞虫，是益虫。幼虫称水虿”，生活在水中（有的地区称蚂螂”），如～～点水”（喻做事肤浅不深入）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蜻"},{"id":"glyph-seal-8747","script":"seal","character":"蝇","reading":"yíng","description":"多指苍蝇。动物名。属昆虫类中的双翅类","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝇"},{"id":"glyph-seal-8748","script":"seal","character":"蝈","reading":"guō","description":"蛤蟆\n蝈蝈儿\n出清脆的声音","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝈"},{"id":"glyph-seal-8749","script":"seal","character":"蝉","reading":"chán","description":"古代一种极薄的丝织品。以其薄如蝉翼而得名\n连续不断\n蝉 chán同翅目昆虫。种类很多，雄的腹部有发音器，能连续不断发出尖锐的声音。幼虫生活在土里。俗称知了。\n【蝉联】连续不断～羽毛球女子单打世界冠军。\n【蝉蜕】\n①〈生〉蝉的幼虫变为成虫时蜕下的壳。中医用作解热镇静的药物。又叫蝉衣。\n②比喻解脱。\n【蝉衣】见【蝉蜕】。\n⒈昆虫。俗叫\"知了\"。雄的腹部有发音器，鸣声高大。幼虫在土中生活。蚱蝉的蜕壳叫\"蝉蜕\"或\"蝉衣\"，可供药用。\n蝉tí 1.黏蝉，汉代县名。在今朝鲜境内。\n蝉shàn 1.见\"蜿蝉\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝉"},{"id":"glyph-seal-874e","script":"seal","character":"蝎","reading":"xiē","description":"xiē：节肢动物，胎生。头胸部的螯肢呈钳状，胸脚四对◇腹狭长，末端有毒钩，用来防敌和捕虫，食昆虫、蜘蛛等。干燥虫体可入药～子。毒如蛇～。\n〔～虎〕即壁虎”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝎"},{"id":"glyph-seal-8753","script":"seal","character":"蝓","reading":"yú","description":"yú：〔蛞～〕见蛞”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝓"},{"id":"glyph-seal-8757","script":"seal","character":"蝗","reading":"huáng","description":"huáng：〔～虫〕昆虫，种类很多，躯体绿色或黄褐色。咀嚼式口器，后足适于弹跳，常常成群飞翔，是农业害虫，亦称蚂（mà）蚱”；简称蝗”，如～灾”，灭～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝗"},{"id":"glyph-seal-8759","script":"seal","character":"蝙","reading":"biān","description":"biān：〔～蝠〕哺乳动物，头和身体的样子像老鼠。前后肢都有薄膜和身体连着，夜间在空中飞，捕食蚊蛾等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝙"},{"id":"glyph-seal-8760","script":"seal","character":"蝠","reading":"fú","description":"fú：〔蝙～〕见蝙”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝠"},{"id":"glyph-seal-8765","script":"seal","character":"蝥","reading":"móu；máo","description":"máo：〔斑～〕昆虫，腿细长，鞘翅上黄黑色斑纹，成虫桅农作物，可入药。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝥"},{"id":"glyph-seal-876e","script":"seal","character":"蝮","reading":"fù","description":"fù：〔～蛇〕体色灰褐，有斑纹，头部略呈三角形，有毒牙。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝮"},{"id":"glyph-seal-8776","script":"seal","character":"蝶","reading":"dié","description":"dié：〔蝴～〕昆虫，翅膀阔大，颜色美丽，静止时四翅竖立在背部，吸花蜜，种类很多，亦作胡蝶”；简称蝶”，如彩～”，～骨”（人的头骨之一），～泳”（游泳的一种姿势，亦是游泳项目之一，形似蝶飞）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝶"},{"id":"glyph-seal-877c","script":"seal","character":"蝼","reading":"lóu","description":"谓肉有臭味如蝼蛄\n谓被蚁蛀蚀\n蝼蛄\n称蝲蝲蛄”,有","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蝼"},{"id":"glyph-seal-8782","script":"seal","character":"螂","reading":"láng","description":"láng：〔螳～〕见螳”。\n〔蜣～〕见蜣”。\n〔蟑～〕见蟑”。\n〔蚂（mā）～〕见蚂2”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-螂"},{"id":"glyph-seal-878d","script":"seal","character":"融","reading":"róng","description":"róng：(1)固体受热变软或化为流体～化。～解。消～。\n(2)调合，和谐～合。～洽。～汇贯通。其乐～～。\n(3)流通～泄（飘动，浮动）。金～（货币的流通，即储蓄，信贷、汇兑、股票和证券交易等经济活动的总称）。\n(4)长远、永久～裔（形容声调悠长）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-融"},{"id":"glyph-seal-879f","script":"seal","character":"螟","reading":"míng","description":"míng：〔～虫〕螟蛾的幼虫，有许多种，如三化螟”、玉米螟”等。桅农作物。\n〔～蛉〕a.一种绿色小虫，螟蛉蛾的幼虫。b.喻抱养的孩子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-螟"},{"id":"glyph-seal-87ab","script":"seal","character":"螫","reading":"shì","description":"毒虫或某些动物用毒刺刺入皮肉。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-87ad","script":"seal","character":"螭","reading":"chī","description":"chī：(1)古代传说中一种没有角的龙。古建筑或器物、工艺品上常用它的形状作装饰～头。\n(2)古同魑”，魑魅。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-螭"},{"id":"glyph-seal-87b3","script":"seal","character":"螳","reading":"táng","description":"táng：〔～螂〕昆虫，全身绿色或土黄色，头呈三角形，前脚呈镰刀状。捕食害虫，对农业有益，如～～捕蝉，黄雀在后”。俗称刀螂”；简称螳”，如～臂当车”（喻不自量力）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-螳"},{"id":"glyph-seal-87ba","script":"seal","character":"螺","reading":"luó","description":"luó：(1)软体动物，体外包着锥形、纺锤形或椭圆形的硬壳，上有旋纹～蛳。田～。～。～号。～钿。法～（用海螺壳做成的佛教乐器）。\n(2)像螺壳纹理的～纹。～旋。～钉。～母。～栓。～髻（古代妇女似螺壳的发形）。\n(3)同脶”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-螺"},{"id":"glyph-seal-87bd","script":"seal","character":"螽","reading":"zhōng","description":"zhōng：〔～斯〕昆虫，身体绿色或褐色，善跳跃，对农作物有害。\n〔阜～〕即蚱蜢”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-螽"},{"id":"glyph-seal-87c6","script":"seal","character":"蟆","reading":"má","description":"m：〔蛤（há）～〕见蛤2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟆"},{"id":"glyph-seal-87ca","script":"seal","character":"蟊","reading":"máo","description":"máo：吃苗根的害虫～贼（喻坏人）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟊"},{"id":"glyph-seal-87cb","script":"seal","character":"蟋","reading":"xī","description":"xī：〔～蟀〕昆虫，身体黑褐色，触角长，善于跳跃。雄性好斗，两翅摩擦能发声，对农作物有害。亦称促织”、趋织”；俗称蛐蛐儿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟋"},{"id":"glyph-seal-87e0","script":"seal","character":"蟠","reading":"pán","description":"pán：屈曲，环绕，盘伏～蜿。～萦。～结。～踞（亦作蟠据”）。～道。～龙。～螭纹（中国春秋战国青铜器上纹饰之一，以盘曲的龙蛇组成）。～夔纹（中国殷和西周青铜器上纹饰之一，以盘曲的夔龙组成）。龙～虎踞。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟠"},{"id":"glyph-seal-87e5","script":"seal","character":"蟥","reading":"huáng","description":"huáng：〔蚂（mǎ）～〕见蚂1”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟥"},{"id":"glyph-seal-87ea","script":"seal","character":"蟪","reading":"huì","description":"huì：〔～蛄〕一种小蝉，青紫色，吻长，身体短。亦称伏天儿”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟪"},{"id":"glyph-seal-87f9","script":"seal","character":"蟹","reading":"xiè","description":"xiè：〔螃～〕节肢动物，水陆两栖。全身有甲壳，足有五对，前双足成钳状，称螯”，横着爬。腹部分节，俗称脐”，雄性脐呈长尖形，雌性脐呈椭圆形。简称蟹”，如河～”，海～”，～黄”，～青”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蟹"},{"id":"glyph-seal-8813","script":"seal","character":"蠓","reading":"měng","description":"měng：昆虫的一科，比蚊子小，褐色或黑色。雌蠓吸人畜的血。能传染疾病。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蠓"},{"id":"glyph-seal-8815","script":"seal","character":"蠕","reading":"rú","description":"rú：像蚯蚓那样慢慢地爬动～动。～～。～形动物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蠕"},{"id":"glyph-seal-8816","script":"seal","character":"蠖","reading":"huò","description":"huò：〔尺～〕尺蠖蛾的幼虫，生长在树上，行动时身体一屈一伸地前进，是害虫。简称蠖”，如～屈”（喻人不得志，屈身退隐。意为暂时的屈身是为求得日后的伸展）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蠖"},{"id":"glyph-seal-8821","script":"seal","character":"蠡","reading":"lí；lǐ","description":"lǐ：虫蛀木，引申为器物经久磨损要断的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蠡"},{"id":"glyph-seal-8822","script":"seal","character":"蠢","reading":"chǔn","description":"chǔn：(1)愚笨，笨拙～人。～材。～话。～事。～然。～拙。～笨。\n(2)虫子蠕动～动。～～。～～欲动（指坏人伺机欲动或敌人准备进犯）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蠢"},{"id":"glyph-seal-8832","script":"seal","character":"蠲","reading":"juān","description":"juān：(1)除去，免除～除。～免。\n(2)显示，昭明惠公～其大德”。\n(3)古同涓”，清洁。\n(4)古代称一种多足虫。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蠲"},{"id":"glyph-seal-8839","script":"seal","character":"蠹","reading":"dù","description":"dù：(1)蛀蚀器物的虫子～虫。木～。书～。～鱼。\n(2)蛀蚀流水不腐，户枢不～。～蛀。～害。～弊（弊病，弊端）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-蠹"},{"id":"glyph-seal-8840","script":"seal","character":"血","reading":"xuè；xie","description":"xuè：(1)人或动物体内循环系统的不透明液体，大多为红色，主要成分为血浆”、血细胞”和血绣”。味咸而腥～型。～脂。～压。～糖。～迹。～汗。～泪。～洗。～书。～雨腥风。～海深仇。\n(2)人类因生育而自然形成的关系～统。～缘。\n(3)喻刚强热烈～性。～气方刚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-血"},{"id":"glyph-seal-8844","script":"seal","character":"衄","reading":"nǜ；nv","description":"nǜ：(1)鼻出血鼻～。\n(2)损伤，挫败败～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衄"},{"id":"glyph-seal-8845","script":"seal","character":"衅","reading":"xìn","description":"⒈〈古〉一种祭祀仪式，用牲畜的血涂在新制的器物上～鼓。～钟。〈引〉涂抹～面。\n⒉缝隙，破绽乘～。〈引〉争端，事端挑～。寻～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衅"},{"id":"glyph-seal-884c","script":"seal","character":"行","reading":"xíng；háng","description":"xíng：行走、行动、实行；也指品行。háng：行列、行业；某些营业机构，如银行。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-884d","script":"seal","character":"衍","reading":"yǎn","description":"yǎn：(1)延长，开展～绎。～生。推～。展～。敷～。～生物。\n(2)多余的（指文字）～文（书籍中因缮写、刻板、排版错误而多出来的字句）。\n(3)低而平坦之地～沃（土地平坦肥美。亦作沃衍”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衍"},{"id":"glyph-seal-8854","script":"seal","character":"衔","reading":"xián","description":"口含\n怀藏\n奉接,接受\n把两物互相接起来或缚住\n包含,\n⒈马嚼子勒紧～。\n⒉用嘴含，包含，含有结草～环。～花。～远山。\n⒊藏在心中，怀恨～悲。～恨。\n⒋奉，接受～命。\n⒌相接～接。\n⒍职位，职称职～。头～。官～。军～。大使～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衔"},{"id":"glyph-seal-8857","script":"seal","character":"街","reading":"jiē","description":"jiē：(1)两边有房屋的、比较宽阔的道路，通常指开设商店的地方～道。～市。～巷。～坊。\n(2)方言，集市赶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-街"},{"id":"glyph-seal-8859","script":"seal","character":"衙","reading":"yá","description":"yá：(1)旧时官署之称公～。～门。～参（cān）（官吏到上司衙门，排班参见，禀白公事）。～役。\n(2)唐代皇帝前殿元和十五年正月……群臣始朝于宣政～”。\n(3)排列成行的事物槐～。柳～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衙"},{"id":"glyph-seal-8861","script":"seal","character":"衡","reading":"héng","description":"héng：(1)秤杆，泛指秤～器。～镜（借指辨别是非善恶的标准）。～鉴（衡镜）。\n(2)称量～钧（借指执掌国政之权）。\n(3)反复思索做出决定，比较评定权～。～情度理。\n(4)平，对等平～。均～。\n(5)指北斗星～汉（北斗星和银河）。\n(6)古同横”，纵横。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衡"},{"id":"glyph-seal-8862","script":"seal","character":"衢","reading":"qú","description":"qú：大路，四通八达的道路通～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衢"},{"id":"glyph-seal-8863","script":"seal","character":"衣","reading":"yī","description":"yī：(1)人穿在身上用以蔽体的东西～服。～着（zhuó）。～冠。～架。～锦还（huán）乡。\n(2)披或包在物体外面的东西炮～。糖～。肠～。\n(3)中医把胎盘和胎膜统称为胞衣”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衣"},{"id":"glyph-seal-8865","script":"seal","character":"补","reading":"bǔ","description":"修补;整修破旧的东西\n补充\n①添上材料，修复破损的东西～衣服。\n③补养滋～。\n④利益；用处于事无～。\n【补白】报刊上填补空白的短文。\n【补集】在研究集合与集合之间的关系时，这些集合常常是某一个给定的集合的子集，这个给定的集合叫全集。用符号i表示。\n【补角】两角的和是平角，那么其中的一个角叫做另一个角的补角，即a+b=180°，a和b互为补角。\n【补苴罅漏】补好裂缝，堵住漏洞。比喻弥补缺漏。苴用草铺垫鞋底。罅孔隙。\n【补偏救弊】补救偏差疏漏，纠正缺点错误。\n【补体】人和动物新鲜血清中的一组球蛋白。单独不作用于抗体或抗原，被抗体抗原复合物等激活后，有促进吞噬、加强炎症反应作用，可扩大机体的免疫应答。\n【补叙】叙述方法之一。在叙述过程中对有关情况、事物作简要的、片断性的解释或说明，对原来的叙述起着补充、丰富的作用。\n【补遗】\n【补益】\n①益处。\n②产生益处。\n【补语】谓语后面或其它动词形容词性中心语后面的补充说明成分。表示动作的情况、结果、数量、性状的程度等。常作补语的是形容词和副词。如'来得快'中的'快'。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-补"},{"id":"glyph-seal-8868","script":"seal","character":"表","reading":"biǎo","description":"①事物的外表～皮、～里不一。\n②表亲～叔、～姐。\n③表示略～心意。\n④用药物把感受的风寒发散出来～寒气。\n⑤榜样；模范～率、为人师～。\n⑧古代测日影的标杆。参见【圭表】。\n⑨计时、测量的器具钟～、体温～、水～。\n【表白】向人表明自己的意思自我～。\n【表达式】用运算符号把数、变量等连接起来构成的式子。\n【表里如一】比喻人的思想和言行相一致。\n【表露】流露；显示出来。\n【表面波】见【地波】。\n【表面化学】研究在不均相物系中，存在于异相界面间的物理和化学现象的一门学科。如在固-气、固-液、液-气等界面间的吸附作用、接触作用、电动现象等。\n【表面积】物体表面的面积总和。\n【表面文章】比喻只讲空话，不办实事这个人就会做～。\n【表面张力】液体表面相邻两部分间单位长度内的相互牵引力。是分子力的一种表现。其大小与液体的性质、纯度和温度有关。由于表面张力的作用，液体表面积总是收缩到尽\n可能小。\n【表皮】动植物体表面的起保护等作用的组织。\n【表率】好的榜样他是我们年轻人的～。\n【表现手法】见【艺术手法】。\n【表现型】基因型在一定条件下所表达的性状总和。是基因型的表现形式，但表现型相同，基因型不一定相同。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-表"},{"id":"glyph-seal-886b","script":"seal","character":"衫","reading":"shān","description":"shān：上衣，单褂长～。衬～」～。棉毛～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衫"},{"id":"glyph-seal-886e","script":"seal","character":"衮","reading":"gǔn","description":"gǔn：古代君王等的礼服～服。～衣。～冕。华～（色彩绚丽的官服）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衮"},{"id":"glyph-seal-8870","script":"seal","character":"衰","reading":"shuāi；cui","description":"shuāi：事物发展转向微弱～微。～弱。～老。盛（shèng）～。兴（xīng）～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衰"},{"id":"glyph-seal-8877","script":"seal","character":"衷","reading":"zhōng","description":"zhōng：(1)内心由～。苦～。无动于～。～肠。\n(2)福，善降～于下民”。\n(3)正中不偏折～。\n(4)贴身的内衣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衷"},{"id":"glyph-seal-887d","script":"seal","character":"衽","reading":"rèn","description":"rèn：(1)衣襟连～成帷”。敛～。\n(2)衣袖。\n(3)古代睡觉时用的席子～席。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衽"},{"id":"glyph-seal-887e","script":"seal","character":"衾","reading":"qīn","description":"qīn：(1)被子～枕。\n(2)尸体入殓时盖尸的东西。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衾"},{"id":"glyph-seal-887f","script":"seal","character":"衿","reading":"jīn","description":"jīn：(1)古代服装下连到前襟的衣领青～（代称秀才）。\n(2)系衣裳的带子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-衿"},{"id":"glyph-seal-8881","script":"seal","character":"袁","reading":"yuán","description":"yuán：姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袁"},{"id":"glyph-seal-8882","script":"seal","character":"袂","reading":"mèi","description":"袂mèi袖子分～（离别）。联～（结伴）赴京。以～掩面。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袂"},{"id":"glyph-seal-8884","script":"seal","character":"袄","reading":"ǎo","description":"皮衣之类的御寒衣服\n泛指上衣。如棉袄;夹袄","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袄"},{"id":"glyph-seal-8885","script":"seal","character":"袅","reading":"niǎo","description":"以系带系马。代称马名\n缭绕;缠绕\n摇曳\n吹拂\n①草木柔弱细长的样子竹竿何～ ～。\n②体态柔美的样子～ ～素女。\n③烟气缭绕的样子炉烟～ ～。\n④声音婉转悠扬，绵延不绝余音～ ～。\n⑤微风吹拂的样子～ ～兮秋风。\n①草木柔弱细长的样子柳丝～娜。\n②体态轻盈柔美的样子少女～娜。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袅"},{"id":"glyph-seal-888b","script":"seal","character":"袋","reading":"dài","description":"dài：(1)用布或皮做的盛东西的器物～子。布～。衣～。口～。旅行～。\n(2)量词，用于袋装的东西和水烟、旱烟一～儿面粉。一～烟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袋"},{"id":"glyph-seal-888d","script":"seal","character":"袍","reading":"páo","description":"páo：(1)中式长衣～子。长～。旗～。棉～。皮～。同～（旧时军人相称）。～泽（袍”和泽”均为古代衣服，后以此称军队中的同事，如～～之谊”、～～故旧”）。\n(2)衣服的前襟反袂拭面，涕沾～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袍"},{"id":"glyph-seal-8892","script":"seal","character":"袒","reading":"tǎn","description":"tǎn：(1)脱去上衣，露出身体的一部分～露。\n(2)不公正地维护一方～护。偏～。左～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袒"},{"id":"glyph-seal-8896","script":"seal","character":"袖","reading":"xiù","description":"xiù：(1)衣服套在胳膊上的部分～子。套～。～标。\n(2)藏在袖子里～藏。～手旁观。～刃（袖藏利刃）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袖"},{"id":"glyph-seal-88a2","script":"seal","character":"袢","reading":"pàn","description":"pàn：同襻”。\n〔袷（qiā）～〕见袷3”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袢"},{"id":"glyph-seal-88a4","script":"seal","character":"袤","reading":"mào","description":"mào：长度，特指南北距离的长度广～。～延（指横长）。周～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袤"},{"id":"glyph-seal-88ab","script":"seal","character":"被","reading":"bèi；pī","description":"bèi：(1)睡觉时覆盖身体的东西～子。～单。棉～。毛巾～。羽绒～。～褥。\n(2)盖，遮覆～覆。泽～后世（恩惠遍及后代）。\n(3)遭遇，遭受～灾。～难（nàn）。\n(4)介词，用在句中表示主讲是受事者他～（老板）辞退了。\n(5)用在动词前，表示受动～动。～告。～批评。～剥削。\npī：古同披”，覆盖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-被"},{"id":"glyph-seal-88ad","script":"seal","character":"袭","reading":"xí","description":"衣一套为一袭\n⒈乘人不备而攻击～击。夜～。奇～。\n⒉因循，继承，照样做因～。世～。抄～。沿～。\n⒊侵入侵～‘气～人。\n⒋量词。一副，一套衣服一～。一～被褥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袭"},{"id":"glyph-seal-88b7","script":"seal","character":"袷","reading":"jiá；jié；qiā","description":"jiá：同夹2”①。\njié：古代交叠于胸前的衣领。\nqiā：〔～袢〕无领大衣；中国维吾尔和塔吉克等民族的对襟长袍。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-袷"},{"id":"glyph-seal-88c1","script":"seal","character":"裁","reading":"cái","description":"cái：(1)用剪子剪布或用刀子割纸～剪。～缝。～衣。对～。\n(2)减除，去掉一部分～减。～军。～员。\n(3)决定，判断～判。～夺（考虑决定）。～决。～度（duó）。～断。\n(4)安排取舍体～。别～。独出心～。\n(5)节制，抑止制～。独～。\n(6)杀自～。\n(7)古同才”，仅，方。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裁"},{"id":"glyph-seal-88c2","script":"seal","character":"裂","reading":"liè；liě","description":"liè：破开，开了缝（fèng）～开。～纹。～缝。～痕。～变（原子核分裂成几个其他原子核，并放出中子的过程）。～隙。～罅（裂缝）。分～。破～。决～。割～。扯～。\nliě：物体的两部分向两旁分开～着怀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裂"},{"id":"glyph-seal-88c5","script":"seal","character":"装","reading":"zhuāng","description":"服装\n亦泛指物品\n⒈行李行～。整～待发。\n⒉打扮，又指演员的打扮～扮。乔～。化～。卸～。\n⒊安置，盛放～置。～箱。～载。～船。～货。安～。～电话。\n⒋修配或组合成整体～修。～配。组～。\n⒌衣服服～。中山～。春秋～。\n⒍修饰，裱衬～饰。～点。～裱。～潢。\n⒎订制成册、籍～订。精～。平～本。\n⒏假作，故意做作假～。～模作样。～聋作哑。～腔作势。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-装"},{"id":"glyph-seal-88ce","script":"seal","character":"裎","reading":"chéng；chěng","description":"chéng：(1)脱衣露体。\n(2)古代系玉佩的带子。\nchěng：古代一种对襟单衣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裎"},{"id":"glyph-seal-88d4","script":"seal","character":"裔","reading":"yì","description":"yì：(1)衣服的边缘。\n(2)边，边远的地方海～。四～。\n(3)后代子孙后～。华～。\n(4)姓。\n〔～～〕ａ．四散流布的样子，如淫淫～～，缘陵流泽”；ｂ．形容舞姿或步履袅娜；如纡长袖而屡舞，翩跹跹以～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裔"},{"id":"glyph-seal-88d5","script":"seal","character":"裕","reading":"yù","description":"yù：(1)丰富，宽绰宽～。富～。充～。节用～民。\n(2)从容，不紧张费力应付～如。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裕"},{"id":"glyph-seal-88d8","script":"seal","character":"裘","reading":"qiú","description":"qiú：(1)皮衣狐～。集腋成～。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裘"},{"id":"glyph-seal-88d9","script":"seal","character":"裙","reading":"qún","description":"qún：(1)一种围在腰以下的服装～子。～钗。筒～。连衣～。百褶～。\n(2)像裙子的东西墙～。鳖～。～礁（海岸边的珊瑚礁）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裙"},{"id":"glyph-seal-88e8","script":"seal","character":"裨","reading":"bì；pí","description":"bì：增添，补助大有～益。～补。\npí：(1)古代的次等礼服。\n(2)副，偏，小～将。偏～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裨"},{"id":"glyph-seal-88f3","script":"seal","character":"裳","reading":"shang；cháng","description":"cháng：古代指遮蔽下体的衣裙。\n〔～～〕光明。\nsh：〔衣～〕衣服。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裳"},{"id":"glyph-seal-88f4","script":"seal","character":"裴","reading":"péi","description":"péi：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裴"},{"id":"glyph-seal-88f8","script":"seal","character":"裸","reading":"luǒ","description":"luǒ：露出，没有遮盖～露。～体。～裎（脱衣露体）。赤～～。～子植物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-裸"}];
